/*
 * admin.css — Admin-specific styles for the Recruitment Plugin HRD dashboard.
 *
 * Public styles are in public.css (shared base).
 * Add admin-only overrides and components here.
 *
 * TODO: Tambahkan style khusus admin sesuai kebutuhan.
 */

.daw-applicants-page {
  margin: 20px 20px 0 0;
  max-width: none;
}

.daw-applicants__header {
  align-items: center;
  display: flex;
  justify-content: space-between;
  margin-bottom: 20px;
}

.daw-applicants__breadcrumb {
  color: #6b7280;
  font-size: 12px;
  margin: 0 0 8px;
  text-transform: uppercase;
}

.daw-applicants__header h1 {
  color: #111827;
  font-size: 32px;
  margin: 0;
}

.daw-applicants__subtitle {
  color: #6b7280;
  margin: 8px 0 0;
}

.daw-applicants__back {
  align-items: center;
  background: #fff;
  border: 1px solid #d1d5db;
  border-radius: 10px;
  color: #111827;
  display: inline-flex;
  font-weight: 600;
  padding: 10px 16px;
  text-decoration: none;
}

.daw-applicant-filter-panel {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  margin-bottom: 22px;
  padding: 18px;
}

.daw-applicant-filter-panel__row {
  align-items: center;
  display: grid;
  gap: 12px;
  grid-template-columns: minmax(220px, 2.5fr) repeat(4, minmax(120px, 1fr)) auto auto;
}

.daw-applicant-search {
  align-items: center;
  background: #f9fafb;
  border: 1px solid #d1d5db;
  border-radius: 10px;
  display: flex;
  gap: 8px;
  padding: 0 12px;
}

.daw-applicant-search .dashicons {
  color: #6b7280;
}

.daw-applicant-search input,
.daw-applicant-filter-panel select {
  background: transparent;
  border: 0;
  box-shadow: none;
  color: #111827;
  font-size: 14px;
  height: 46px;
  outline: none;
  width: 100%;
}

.daw-applicant-filter-panel select {
  background: #f9fafb;
  border: 1px solid #d1d5db;
  border-radius: 10px;
  padding: 0 12px;
}

.daw-applicant-filter-panel__submit,
.daw-applicant-filter-panel__reset,
.daw-detail-button,
.daw-document-btn {
  border-radius: 10px;
  font-weight: 600;
  padding: 11px 16px;
  text-decoration: none;
}

.daw-applicant-filter-panel__submit,
.daw-detail-button {
  background: #111827;
  border: 1px solid #111827;
  color: #fff;
  cursor: pointer;
}

.daw-applicant-filter-panel__reset {
  align-items: center;
  background: #fff;
  border: 1px solid #d1d5db;
  color: #374151;
  display: inline-flex;
  justify-content: center;
}

.daw-applicant-stats {
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 22px;
}

.daw-applicant-stat-card {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  padding: 18px 20px;
}

.daw-applicant-stat-card span {
  color: #6b7280;
  display: block;
  font-size: 11px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.daw-applicant-stat-card strong {
  display: block;
  font-size: 32px;
  line-height: 1.2;
  margin-top: 10px;
}

.daw-applicant-stat-card--dark { border-top: 4px solid #111827; }
.daw-applicant-stat-card--green { border-top: 4px solid #16a34a; }
.daw-applicant-stat-card--blue { border-top: 4px solid #2563eb; }
.daw-applicant-stat-card--red { border-top: 4px solid #dc2626; }

.daw-applicant-table-card {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  overflow: hidden;
}

.daw-applicant-table-card__top {
  border-bottom: 1px solid #e5e7eb;
  padding: 18px 22px;
}

.daw-applicant-table-card__label {
  color: #6b7280;
  display: block;
  font-size: 11px;
  margin-bottom: 6px;
  text-transform: uppercase;
}

.daw-applicant-table-wrap {
  overflow-x: auto;
}

.daw-applicant-table {
  border-collapse: collapse;
  min-width: 1180px;
  width: 100%;
}

.daw-applicant-table thead th {
  background: #f9fafb;
  color: #4b5563;
  font-size: 12px;
  font-weight: 700;
  padding: 14px 16px;
  text-align: left;
  text-transform: uppercase;
}

.daw-applicant-table tbody td {
  border-top: 1px solid #e5e7eb;
  color: #111827;
  padding: 16px;
  vertical-align: top;
}

.daw-applicant-name-cell {
  align-items: center;
  display: flex;
  gap: 12px;
}

.daw-applicant-name-cell__avatar {
  align-items: center;
  background: #f3f4f6;
  border-radius: 50%;
  color: #111827;
  display: inline-flex;
  font-weight: 700;
  height: 36px;
  justify-content: center;
  width: 36px;
}

.daw-applicant-name-cell strong,
.daw-applicant-position-cell strong {
  display: block;
  font-size: 15px;
}

.daw-applicant-name-cell small,
.daw-applicant-position-cell small {
  color: #6b7280;
  display: block;
  font-size: 12px;
  margin-top: 4px;
}

.daw-year-badge,
.daw-stage-badge,
.daw-status-badge {
  border-radius: 999px;
  display: inline-flex;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  padding: 7px 10px;
}

.daw-year-badge {
  background: #f3f4f6;
  color: #374151;
}

.daw-stage-badge--lamaran-diterima,
.daw-stage-badge--seleksi-administrasi,
.daw-stage-badge--psikotes,
.daw-stage-badge--wawancara-hr,
.daw-stage-badge--wawancara-user,
.daw-stage-badge--keputusan-akhir {
  background: #eff6ff;
  color: #1d4ed8;
}

.daw-status-badge--diterima {
  background: #dcfce7;
  color: #166534;
}

.daw-status-badge--dalam_proses,
.daw-status-badge--sedang-berlangsung {
  background: #dbeafe;
  color: #1d4ed8;
}

.daw-status-badge--tidak_diterima,
.daw-status-badge--tidak-lolos {
  background: #fee2e2;
  color: #b91c1c;
}

.daw-status-badge--dipertimbangkan_kembali,
.daw-status-badge--belum-dimulai {
  background: #fef3c7;
  color: #92400e;
}

.daw-note-cell {
  color: #4b5563;
  max-width: 240px;
}

.daw-social-cell {
  align-items: center;
  display: flex;
  gap: 8px;
}

.daw-social-cell a {
  align-items: center;
  background: #f3f4f6;
  border-radius: 8px;
  color: #111827;
  display: inline-flex;
  font-weight: 700;
  height: 28px;
  justify-content: center;
  text-decoration: none;
  width: 28px;
}

.daw-detail-button {
  display: inline-block;
  text-decoration: none;
}

.daw-empty-state {
  background: #f9fafb;
  border: 1px dashed #d1d5db;
  border-radius: 12px;
  color: #4b5563;
  padding: 28px 20px;
  text-align: center;
}

.daw-applicant-profile-card {
  align-items: center;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 16px;
  display: flex;
  gap: 18px;
  margin-bottom: 18px;
  padding: 20px;
}

.daw-applicant-profile-card__avatar {
  align-items: center;
  background: #f3f4f6;
  border-radius: 50%;
  color: #111827;
  display: inline-flex;
  font-size: 26px;
  font-weight: 700;
  height: 74px;
  justify-content: center;
  min-width: 74px;
}

.daw-applicant-profile-card__identity {
  flex: 1;
}

.daw-applicant-profile-card__identity h1 {
  font-size: 32px;
  margin: 0;
}

.daw-applicant-profile-card__code {
  color: #6b7280;
  font-size: 14px;
  margin: 8px 0;
}

.daw-applicant-profile-card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.daw-applicant-profile-card__meta span {
  background: #f3f4f6;
  border-radius: 999px;
  color: #374151;
  font-size: 12px;
  padding: 7px 10px;
}

.daw-detail-contact-row {
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-bottom: 22px;
}

.daw-detail-contact-row__item {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  padding: 18px 20px;
}

.daw-detail-contact-row__item span {
  color: #6b7280;
  display: block;
  font-size: 11px;
  margin-bottom: 8px;
  text-transform: uppercase;
}

.daw-detail-contact-row__item strong {
  color: #111827;
  font-size: 15px;
}

.daw-documents-panel {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  margin-bottom: 22px;
  padding: 20px;
}

.daw-documents-panel h2 {
  margin: 0 0 16px;
}

.daw-documents-panel__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 10px;
}

.daw-document-btn {
  background: #111827;
  border: 1px solid #111827;
  color: #fff;
  cursor: pointer;
}

.daw-document-btn--muted {
  background: #f3f4f6;
  border-color: #d1d5db;
  color: #374151;
}

.daw-documents-panel__hint {
  color: #6b7280;
  margin: 0;
}

.daw-applicant-detail-tabs {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  overflow: hidden;
}

.daw-applicant-detail-tabs__nav {
  background: #f9fafb;
  border-bottom: 1px solid #e5e7eb;
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding: 12px 14px;
}

.daw-applicant-detail-tabs__tab {
  background: transparent;
  border: 1px solid transparent;
  border-radius: 10px;
  color: #374151;
  cursor: pointer;
  font-weight: 600;
  min-height: 38px;
  padding: 8px 14px;
}

.daw-applicant-detail-tabs__tab.is-active {
  background: #111827;
  color: #fff;
}

.daw-applicant-detail-tabs__content {
  padding: 20px;
}

.daw-applicant-detail-panel {
  display: none;
}

.daw-applicant-detail-panel.is-active {
  display: block;
}

.daw-detail-grid {
  display: grid;
  gap: 16px 18px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.daw-detail-field {
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 14px 16px;
}

.daw-detail-field span {
  color: #6b7280;
  display: block;
  font-size: 12px;
  margin-bottom: 8px;
  text-transform: uppercase;
}

.daw-detail-field strong {
  color: #111827;
  font-size: 15px;
}

.daw-selection-history {
  display: grid;
  gap: 18px;
}

.daw-selection-history__item {
  display: grid;
  gap: 12px;
  grid-template-columns: 16px minmax(0, 1fr);
}

.daw-selection-history__marker {
  align-self: start;
  background: #d1d5db;
  border-radius: 50%;
  display: block;
  height: 16px;
  margin-top: 4px;
  width: 16px;
}

.daw-selection-history__marker--selesai {
  background: #16a34a;
}

.daw-selection-history__marker--sedang-berlangsung {
  background: #2563eb;
}

.daw-selection-history__marker--belum-dimulai {
  background: #d1d5db;
}

.daw-selection-history__marker--tidak-lolos {
  background: #dc2626;
}

.daw-selection-history__content {
  border-left: 2px solid #e5e7eb;
  padding-left: 18px;
}

.daw-selection-history__header {
  align-items: center;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.daw-selection-history__header strong {
  color: #111827;
}

.daw-selection-history__content p {
  color: #6b7280;
  margin: 0;
}

@media (max-width: 980px) {
  .daw-applicant-filter-panel__row {
    grid-template-columns: 1fr 1fr;
  }

  .daw-applicant-stats,
  .daw-detail-contact-row,
  .daw-detail-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 782px) {
  .daw-applicants-page {
    margin: 10px 10px 0 0;
  }

  .daw-applicants__header {
    display: block;
  }

  .daw-applicant-profile-card {
    align-items: flex-start;
    display: block;
  }

  .daw-applicant-profile-card__stage {
    margin-top: 12px;
  }

  .daw-applicant-filter-panel__row,
  .daw-applicant-stats,
  .daw-detail-contact-row,
  .daw-detail-grid {
    grid-template-columns: 1fr;
  }

  .daw-applicant-table { min-width: 920px; }
}
.recruitment-admin,
.recruitment-admin * {
  box-sizing: border-box;
}
.recruitment-admin {
  color: #1c1c1e;
  font-family: Inter, Arial, sans-serif;
}
.recruitment-admin__header {
  align-items: center;
  background: #fff;
  border-bottom: 1px solid #d1d1d6;
  display: flex;
  justify-content: space-between;
  min-height: 64px;
  padding: 0 24px;
}
.recruitment-admin__brand {
  align-items: center;
  display: flex;
  font-size: 15px;
  font-weight: 800;
  gap: 9px;
  text-decoration: none;
}
.recruitment-admin__brand span {
  align-items: center;
  background: #c8102e;
  border-radius: 4px;
  color: #fff;
  display: flex;
  height: 30px;
  justify-content: center;
  width: 30px;
}
.recruitment-admin__header nav {
  align-items: center;
  display: flex;
  gap: 18px;
  font-size: 12px;
}
.recruitment-admin__header a {
  color: #6e6e73;
  text-decoration: none;
}
.admin-layout {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  min-height: calc(100vh - 64px);
}
.admin-sidebar {
  background: #1c1c1e;
  color: #fff;
  padding: 18px 10px;
}
.admin-sidebar nav {
  display: grid;
  gap: 3px;
}
.admin-sidebar a {
  border-radius: 5px;
  color: rgba(255, 255, 255, 0.65);
  font-size: 12px;
  padding: 11px 14px;
  text-decoration: none;
}
.admin-sidebar a:hover,
.admin-sidebar a.active {
  background: #c8102e;
  color: #fff;
}
.content-shell {
  padding: 38px;
}
.content-shell h1 {
  font-size: 30px;
  margin: 8px 0;
}
.eyebrow {
  color: #c8102e;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.lede {
  color: #6e6e73;
  font-size: 14px;
}
.stats-row {
  display: grid;
  gap: 14px;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 30px;
}
.stats-card {
  background: #fff;
  border: 1px solid #d1d1d6;
  border-top: 3px solid #c8102e;
  padding: 20px;
}
.stats-card dt {
  color: #6e6e73;
  font-size: 11px;
  text-transform: uppercase;
}
.stats-card dd {
  font-size: 30px;
  font-weight: 800;
  margin: 8px 0 0;
}
.recruitment-admin footer {
  border-top: 1px solid #d1d1d6;
  color: #6e6e73;
  display: flex;
  font-size: 11px;
  justify-content: space-between;
  margin-left: 220px;
  padding: 18px 38px;
}
@media (max-width: 800px) {
  .admin-layout {
    grid-template-columns: 1fr;
  }
  .admin-sidebar {
    padding: 10px;
  }
  .admin-sidebar nav {
    grid-template-columns: repeat(2, 1fr);
  }
  .content-shell {
    padding: 24px 16px;
  }
  .stats-row {
    grid-template-columns: repeat(2, 1fr);
  }
  .recruitment-admin footer {
    margin-left: 0;
    padding: 18px 16px;
  }
}

.recruitment-dashboard.wrap {
  margin: 10px 20px 0 2px;
  max-width: none;
}
.recruitment-dashboard,
.recruitment-dashboard * {
  box-sizing: border-box;
}
.recruitment-dashboard__banner {
  align-items: center;
  background: #fff;
  border: 1px solid #dcdcde;
  display: flex;
  justify-content: space-between;
  min-height: 98px;
  padding: 16px 24px;
}
.recruitment-dashboard__breadcrumb {
  color: #555d66;
  font-size: 12px;
  margin: 0 0 12px;
}
.recruitment-dashboard__breadcrumb span {
  color: #a7acb1;
  padding: 0 5px;
}
.recruitment-dashboard__banner h1 {
  color: #262c33;
  font-size: 22px;
  line-height: 1.25;
  margin: 0 0 4px;
}
.recruitment-dashboard__subtitle {
  color: #737b84;
  font-size: 12px;
  margin: 0;
}
.recruitment-dashboard__active-count {
  align-items: center;
  background: #f5f6f7;
  border-radius: 6px;
  color: #525a63;
  display: flex;
  gap: 6px;
  padding: 8px 12px;
}
.recruitment-dashboard__active-count .dashicons {
  color: #626b75;
  font-size: 16px;
  height: 16px;
  width: 16px;
}
.recruitment-dashboard__active-count strong {
  color: #20262d;
  font-size: 13px;
}
.recruitment-dashboard__active-count span:last-child {
  font-size: 11px;
}
.recruitment-dashboard__pipeline {
  margin: 16px auto 0;
  max-width: 760px;
}
.recruitment-dashboard__section-label,
.recruitment-dashboard__result-count {
  color: #656d76;
  font-size: 10px;
  font-weight: 600;
  margin: 0 0 8px;
  text-transform: uppercase;
}
.recruitment-dashboard__stage-filters {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}
.recruitment-dashboard__stage-filters button {
  align-items: center;
  background: #fff;
  border: 1px solid #d3d7db;
  border-radius: 16px;
  color: #303740;
  cursor: pointer;
  display: inline-flex;
  font-size: 11px;
  font-weight: 600;
  gap: 7px;
  line-height: 1.2;
  min-height: 30px;
  padding: 5px 12px;
}
.recruitment-dashboard__stage-filters button:hover {
  border-color: #bd183b;
}
.recruitment-dashboard__stage-filters button.is-active {
  background: #c8102e;
  border-color: #c8102e;
  color: #fff;
}
.recruitment-dashboard__stage-filters button span {
  background: rgba(0, 0, 0, 0.07);
  border-radius: 10px;
  min-width: 16px;
  padding: 2px 4px;
  text-align: center;
}
.recruitment-dashboard__stage-filters button.is-active span {
  background: rgba(255, 255, 255, 0.2);
}
.recruitment-dashboard__filters {
  align-items: center;
  background: #fff;
  border: 1px solid #d3d7db;
  border-radius: 7px;
  display: grid;
  gap: 7px;
  grid-template-columns:
    minmax(180px, 1fr) minmax(115px, 150px) minmax(115px, 150px)
    auto;
  margin-bottom: 14px;
  padding: 8px;
}
.recruitment-dashboard__filters select,
.recruitment-dashboard__search input {
  background-color: #fff;
  border: 1px solid #d4d8dc;
  border-radius: 5px;
  color: #343b43;
  font-size: 11px;
  height: 32px;
  margin: 0;
  max-width: none;
  min-height: 32px;
  padding: 0 9px;
  width: 100%;
}
.recruitment-dashboard__search {
  align-items: center;
  display: flex;
  gap: 6px;
  min-width: 0;
}
.recruitment-dashboard__search .dashicons {
  color: #707982;
  flex: 0 0 auto;
  font-size: 15px;
  height: 15px;
  width: 15px;
}
.recruitment-dashboard__search input {
  min-width: 0;
}
.recruitment-dashboard__filters .button {
  font-size: 11px;
  height: 32px;
  line-height: 30px;
  min-height: 32px;
  padding: 0 10px;
}
.recruitment-dashboard__result-count {
  margin-bottom: 7px;
}
.recruitment-dashboard__candidate-list {
  display: grid;
  gap: 7px;
}
.recruitment-candidate {
  align-items: center;
  background: #fff;
  border: 1px solid #d1d5da;
  border-radius: 8px;
  display: flex;
  gap: 10px;
  min-height: 66px;
  padding: 9px 11px;
}
.recruitment-candidate__avatar {
  align-items: center;
  background: #fdebea;
  border-radius: 50%;
  color: #bb3440;
  display: inline-flex;
  flex: 0 0 30px;
  font-size: 10px;
  font-weight: 700;
  height: 30px;
  justify-content: center;
  width: 30px;
}
.recruitment-candidate__identity {
  flex: 1 1 auto;
  min-width: 0;
}
.recruitment-candidate__identity h2 {
  color: #2b3036;
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
  margin: 0 0 2px;
}
.recruitment-candidate__identity p {
  color: #707780;
  font-size: 10px;
  line-height: 1.4;
  margin: 0;
  overflow-wrap: anywhere;
}
.recruitment-candidate__identity p span {
  color: #b0b5ba;
  padding: 0 2px;
}
.recruitment-candidate__identity .recruitment-candidate__position {
  color: #505862;
  margin-top: 2px;
}
.recruitment-candidate__status {
  align-items: flex-end;
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
  gap: 5px;
}
.recruitment-candidate__stage,
.recruitment-candidate__state {
  border-radius: 10px;
  font-size: 9px;
  font-weight: 600;
  line-height: 1.2;
  padding: 3px 7px;
  white-space: nowrap;
}
.recruitment-candidate__stage--administration {
  background: #e7efff;
  color: #2458be;
}
.recruitment-candidate__stage--psychological_test {
  background: #fff1ca;
  color: #986300;
}
.recruitment-candidate__stage--hr_interview {
  background: #f2eaff;
  color: #7741bc;
}
.recruitment-candidate__stage--user_interview {
  background: #e5edff;
  color: #385bb5;
}
.recruitment-candidate__stage--final {
  background: #e6f5eb;
  color: #27783f;
}
.recruitment-candidate__stage--other {
  background: #edf0f2;
  color: #505862;
}
.recruitment-candidate__state {
  background: #e8f0ff;
  color: #2856a8;
}
.recruitment-dashboard__empty {
  background: #fff;
  border: 1px dashed #c8cdd2;
  border-radius: 7px;
  color: #606972;
  font-size: 12px;
  line-height: 1.5;
  padding: 28px 18px;
  text-align: center;
}
.recruitment-dashboard [hidden] {
  display: none !important;
}

@media (max-width: 782px) {
  .recruitment-dashboard.wrap {
    margin: 10px 10px 0 0;
  }
  .recruitment-dashboard__banner {
    align-items: flex-start;
    gap: 14px;
    padding: 14px;
  }
  .recruitment-dashboard__active-count {
    flex: 0 0 auto;
  }
  .recruitment-dashboard__filters {
    grid-template-columns: 1fr 1fr;
  }
  .recruitment-dashboard__search {
    grid-column: 1 / -1;
  }
  .recruitment-dashboard__filters .button {
    justify-self: start;
  }
}

@media (max-width: 480px) {
  .recruitment-dashboard__banner {
    flex-direction: column;
  }
  .recruitment-dashboard__active-count {
    align-self: flex-start;
  }
  .recruitment-dashboard__filters {
    grid-template-columns: 1fr;
  }
  .recruitment-dashboard__search {
    grid-column: auto;
  }
  .recruitment-candidate {
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .recruitment-candidate__identity {
    flex-basis: calc(100% - 42px);
  }
  .recruitment-candidate__status {
    flex-direction: row;
    margin-left: 40px;
  }
}

.recruitment-dashboard.wrap {
  color: #25282d;
  margin: 0 20px 24px 2px;
  max-width: none;
}
.recruitment-dashboard {
  --dashboard-border: #dedfe3;
  --dashboard-muted: #747982;
  --dashboard-red: #c8102e;
}
.recruitment-dashboard__topbar {
  align-items: center;
  background: #fff;
  border: 1px solid var(--dashboard-border);
  border-radius: 10px;
  display: flex;
  justify-content: space-between;
  margin: 0 0 16px;
  min-height: 56px;
  padding: 8px 16px;
}
.recruitment-dashboard__topbar .recruitment-dashboard__breadcrumb {
  color: #50555c;
  font-size: 12px;
  font-weight: 600;
  margin: 0;
}
.recruitment-dashboard__profile {
  align-items: center;
  border-left: 1px solid #e5e6e9;
  display: flex;
  gap: 9px;
  padding-left: 12px;
}
.recruitment-dashboard__profile-avatar {
  align-items: center;
  background: var(--dashboard-red);
  border-radius: 50%;
  color: #fff;
  display: inline-flex;
  flex: 0 0 30px;
  font-size: 10px;
  font-weight: 700;
  height: 30px;
  justify-content: center;
  width: 30px;
}
.recruitment-dashboard__profile-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.recruitment-dashboard__profile-copy strong {
  color: #272a30;
  font-size: 11px;
  line-height: 1.2;
}
.recruitment-dashboard__profile-copy small {
  color: var(--dashboard-muted);
  font-size: 10px;
}
.recruitment-dashboard__logout {
  border: 1px solid #d8dade;
  border-radius: 5px;
  color: #50555c;
  font-size: 10px;
  margin-left: 8px;
  padding: 6px 10px;
  text-decoration: none;
}
.recruitment-dashboard__logout:hover {
  border-color: var(--dashboard-red);
  color: var(--dashboard-red);
}
.recruitment-dashboard__quick-actions {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 12px;
}
.recruitment-dashboard__quick-card {
  background: #fff;
  border: 1px solid var(--dashboard-border);
  border-radius: 10px;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  min-height: 88px;
  padding: 12px;
  text-decoration: none;
  transition:
    border-color 0.16s ease,
    transform 0.16s ease;
}
.recruitment-dashboard__quick-card:hover {
  border-color: #b9bdc4;
  transform: translateY(-1px);
}
.recruitment-dashboard__quick-card--orange {
  background: #fffaf0;
  border-color: #efd49b;
}
.recruitment-dashboard__quick-card--blue {
  background: #f3f7ff;
  border-color: #bfd2ff;
}
.recruitment-dashboard__quick-card--purple {
  background: #fbf7ff;
  border-color: #e2d1fa;
}
.recruitment-dashboard__quick-card--red {
  background: #fff6f6;
  border-color: #f0c6cb;
}
.recruitment-dashboard__icon {
  align-items: center;
  background: #f1f2f4;
  border-radius: 7px;
  color: #626973;
  display: inline-flex;
  font-size: 14px;
  height: 28px;
  justify-content: center;
  width: 28px;
}
.recruitment-dashboard__quick-card--orange .recruitment-dashboard__icon {
  background: #fff0c9;
  color: #bd7900;
}
.recruitment-dashboard__quick-card--blue .recruitment-dashboard__icon {
  background: #e3edff;
  color: #3166d5;
}
.recruitment-dashboard__quick-card--purple .recruitment-dashboard__icon {
  background: #f0e5ff;
  color: #873fe0;
}
.recruitment-dashboard__quick-card--red .recruitment-dashboard__icon {
  background: #ffe8e9;
  color: #ca2637;
}
.recruitment-dashboard__quick-title {
  align-items: center;
  color: #32363c;
  display: flex;
  font-size: 11px;
  font-weight: 700;
  gap: 6px;
  min-width: 0;
}
.recruitment-dashboard__quick-title b {
  background: var(--dashboard-red);
  border-radius: 10px;
  color: #fff;
  font-size: 9px;
  line-height: 17px;
  margin-left: auto;
  min-width: 17px;
  padding: 0 5px;
  text-align: center;
}
.recruitment-dashboard__quick-description {
  color: var(--dashboard-muted);
  font-size: 10px;
  grid-column: 2;
  line-height: 1.4;
}
.recruitment-dashboard__stats {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 16px;
}
.recruitment-dashboard__stat-card {
  background: #fff;
  border: 1px solid var(--dashboard-border);
  border-radius: 10px;
  display: grid;
  grid-template-columns: 32px 1fr;
  grid-template-rows: auto auto auto;
  min-height: 104px;
  padding: 12px;
}
.recruitment-dashboard__stat-card .recruitment-dashboard__icon {
  grid-row: 1 / 4;
  margin-right: 4px;
}
.recruitment-dashboard__stat-card--blue .recruitment-dashboard__icon {
  background: #e5efff;
  color: #2864dc;
}
.recruitment-dashboard__stat-card--orange .recruitment-dashboard__icon {
  background: #fff1cf;
  color: #c47c00;
}
.recruitment-dashboard__stat-card--red .recruitment-dashboard__icon {
  background: #ffe9e9;
  color: #cf2638;
}
.recruitment-dashboard__stat-card--green .recruitment-dashboard__icon {
  background: #e2f7e9;
  color: #13833d;
}
.recruitment-dashboard__stat-card--purple .recruitment-dashboard__icon {
  background: #f3eaff;
  color: #983fe5;
}
.recruitment-dashboard__stat-card--blue .recruitment-dashboard__stat-value {
  color: #2160da;
}
.recruitment-dashboard__stat-card--orange .recruitment-dashboard__stat-value {
  color: #c97800;
}
.recruitment-dashboard__stat-card--red .recruitment-dashboard__stat-value {
  color: #c8102e;
}
.recruitment-dashboard__stat-card--green .recruitment-dashboard__stat-value {
  color: #12833c;
}
.recruitment-dashboard__stat-card--purple .recruitment-dashboard__stat-value {
  color: #8b39dc;
}
.recruitment-dashboard__stat-value {
  color: #30343b;
  font-size: 21px;
  font-weight: 750;
  line-height: 1.2;
  margin-top: 5px;
}
.recruitment-dashboard__stat-label {
