.daw-question-bank__profile-copy { display: grid; gap: 2px; }
.daw-question-bank__stats { display: grid; gap: 9px; grid-template-columns: repeat(5, minmax(0, 1fr)); margin: 0 0 13px; }
.daw-question-bank__stat { background: #fff; border: 1px solid #d9dce0; border-radius: 7px; color: #343b42; display: grid; gap: 3px; min-height: 53px; padding: 9px 11px; text-decoration: none; }
.daw-question-bank__stat:hover { border-color: #b5bbc1; }
.daw-question-bank__stat strong { font-size: 14px; line-height: 1; }
.daw-question-bank__stat span { color: #737b83; font-size: 9px; }
.daw-question-bank__panel-heading { align-items: flex-start; }
.daw-question-bank__panel-actions { align-items: center; display: flex; flex-wrap: wrap; gap: 7px; justify-content: flex-end; }
.daw-question-bank__filters { align-items: center; display: flex; flex-wrap: wrap; gap: 5px; }
.daw-question-bank__filters select, .daw-question-bank__filters input { font-size: 9px; margin: 0; max-width: 180px; min-height: 30px; }
.daw-question-bank__filters .button, .daw-question-bank__panel-actions > .button { min-height: 30px; }
.daw-question-bank__table-wrap { overflow-x: auto; }
.daw-question-bank__table { border: 0; border-collapse: collapse; min-width: 760px; }
.daw-question-bank__table thead th { background: #f3f4f6; color: #6a737c; font-size: 8px; font-weight: 650; padding: 9px 10px; text-transform: uppercase; }
.daw-question-bank__table tbody td { color: #535c65; font-size: 9px; padding: 9px 10px; vertical-align: middle; }
.daw-question-bank__table tbody td:nth-child(2) { max-width: 390px; }
.daw-question-bank__table tbody td:nth-child(2) strong { color: #353d45; font-size: 9px; font-weight: 550; }
.daw-question-bank__table tbody tr:hover td { background: #fafbfc; }
.daw-question-bank__tag { background: #e8efff; border-radius: 4px; color: #2b5db5; display: inline-flex; font-size: 8px; font-weight: 600; padding: 3px 6px; white-space: nowrap; }
.daw-question-bank__tag--pauli { background: #fff0d6; color: #9a6100; }
.daw-question-bank__tag--personality { background: #ffe7e8; color: #b22e3b; }
.daw-question-bank__tag--disc { background: #e5f4e8; color: #277644; }
.daw-question-bank__tag--papi { background: #eff0f2; color: #535d66; }
.daw-question-bank__tag--type { background: #eff2f5; color: #53606b; }
.daw-question-bank__actions { align-items: center; display: flex; gap: 7px; white-space: nowrap; }
.daw-question-bank__actions button { color: #bb1832; font-size: 8px; text-decoration: none; }
.daw-question-bank__row-action { display: inline; margin: 0; }
.daw-question-bank__row-action button { color: #66717a; }
.daw-question-bank__empty { color: #737b83 !important; padding: 24px !important; text-align: center; }
.daw-question-bank__dialog { border: 1px solid #d6dade; border-radius: 7px; color: #303840; max-width: 560px; padding: 0; width: calc(100% - 28px); }
.daw-question-bank__dialog::backdrop { background: rgba(18, 21, 24, .42); }
.daw-question-bank__dialog form { display: grid; gap: 12px; padding: 16px; }
.daw-question-bank__dialog-heading { align-items: center; display: flex; justify-content: space-between; }
.daw-question-bank__dialog-heading h2 { font-size: 14px; margin: 0; }
.daw-question-bank__dialog-heading button { font-size: 18px; text-decoration: none; }
.daw-question-bank__dialog form > label, .daw-question-bank__dialog-grid label { color: #525a62; display: grid; font-size: 9px; font-weight: 600; gap: 5px; }
.daw-question-bank__dialog label[hidden] { display: none; }
.daw-question-bank__dialog input:not([type="hidden"]), .daw-question-bank__dialog select, .daw-question-bank__dialog textarea { font-size: 10px; margin: 0; max-width: none; width: 100%; }
.daw-question-bank__dialog textarea { min-height: 65px; }
.daw-question-bank__dialog label small { color: #7b838b; font-size: 8px; font-weight: 400; }
.daw-question-bank__dialog-grid { display: grid; gap: 9px; grid-template-columns: repeat(3, minmax(0, 1fr)); }
.daw-question-bank__dialog-actions { display: flex; gap: 7px; justify-content: flex-end; }

@media (max-width: 900px) {
  .daw-psychotest-settings__fields--schedule { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .daw-psychotest-settings__test-layout { grid-template-columns: 1fr; }
  .daw-psychotest-settings__test-list { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .daw-psychotest-settings__test-list h2 { grid-column: 1 / -1; }
  .daw-question-bank__panel-heading { align-items: flex-start; flex-direction: column; }
  .daw-question-bank__panel-actions { justify-content: flex-start; width: 100%; }
}
@media (max-width: 600px) {
  .daw-psychotest-settings, .daw-question-bank { margin: 10px 10px 22px 2px; }
  .daw-psychotest-settings__global-row, .daw-psychotest-settings__fields--schedule, .daw-psychotest-settings__fields--test { grid-template-columns: 1fr; }
  .daw-psychotest-settings__switch--inline { grid-column: auto; }
  .daw-psychotest-settings__test-list { grid-template-columns: 1fr; }
  .daw-question-bank__stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .daw-question-bank__header { align-items: flex-start; gap: 8px; }
  .daw-question-bank__profile strong { display: none; }
  .daw-question-bank__filters { align-items: stretch; display: grid; grid-template-columns: 1fr 1fr; width: 100%; }
  .daw-question-bank__filters input[type="search"] { grid-column: 1 / -1; max-width: none; }
  .daw-question-bank__dialog-grid { grid-template-columns: 1fr; }
}
